1	export type Cell = [number, number];
2	
3	function isSameCell([x, y]: Cell, [otherX, otherY]: Cell): boolean {
4	  return x === otherX && y === otherY;
5	}
6	
7	function isNeighbor(cell: Cell, other: Cell): boolean {
8	  const [x, y] = cell;
9	  const [otherX, otherY] = other;
10	  const isWithinOneStep = Math.abs(x - otherX) <= 1 && Math.abs(y - otherY) <= 1;
11	  return isWithinOneStep && !isSameCell(cell, other);
12	}
13	
14	function countLiveNeighbors(cell: Cell, liveCells: Cell[]): number {
15	  return liveCells.filter((other) => isNeighbor(cell, other)).length;
16	}
17	
18	function survives(liveNeighborCount: number): boolean {
19	  return liveNeighborCount === 2 || liveNeighborCount === 3;
20	}
21	
22	function isAlive(cell: Cell, liveCells: Cell[]): boolean {
23	  return liveCells.some((live) => isSameCell(cell, live));
24	}
25	
26	function neighborsOf([x, y]: Cell): Cell[] {
27	  return [
28	    [x - 1, y - 1],
29	    [x, y - 1],
30	    [x + 1, y - 1],
31	    [x - 1, y],
32	    [x + 1, y],
33	    [x - 1, y + 1],
34	    [x, y + 1],
35	    [x + 1, y + 1],
36	  ];
37	}
38	
39	export function nextGeneration(liveCells: Cell[]): Cell[] {
40	  const survivors = liveCells.filter((cell) =>
41	    survives(countLiveNeighbors(cell, liveCells)),
42	  );
43	
44	  const born = liveCells
45	    .flatMap(neighborsOf)
46	    .filter((cell) => !isAlive(cell, liveCells))
47	    .filter((cell) => countLiveNeighbors(cell, liveCells) === 3)
48	    .filter(
49	      (cell, index, candidates) =>
50	        candidates.findIndex((other) => isSameCell(cell, other)) === index,
51	    );
52	
53	  return [...survivors, ...born];
54	}
