function isAlive(cell: Cell, liveCells: Cell[]): boolean {
  return liveCells.some((live) => isSameCell(cell, live));
}

function reproduces(liveNeighborCount: number): boolean {
  return liveNeighborCount === 3;
}

function withoutDuplicates(cells: Cell[]): Cell[] {
  return cells.filter(
    (cell, index) => !isAlive(cell, cells.slice(0, index)),
  );
}

const deadNeighbors = withoutDuplicates(
  liveCells.flatMap(neighborsOf).filter((cell) => !isAlive(cell, liveCells)),
);

const born = deadNeighbors.filter((cell) =>
  reproduces(countLiveNeighbors(cell, liveCells)),
);
